  ('ict-lec-ch06-mcq-189', 'class9-ict-bn-guide', 'ict-lecture-satt', 'রিমা রামপুরা উচ্চ বিদ্যালয়ে দশম শ্রেণিতে পড়ে। বিদ্যালয়ের ডেটাবেজে তার iii. বাতার্ বক্সেYes বোতামে ক্লিক করতে হবে বণার্নুক্রমিক ডেটা হলো- নিচের কোনটি সঠিক?', 'mcq', '{"ক":"ii","খ":"iii ii. ii ওiii i, ii ওiii ঠিকানা","গ":"iii.","ঘ":"i ওiii"}'::jsonb, 'গ', null, 1, null, 'mcq_bank', null, 6, false),
