  ('ict-lec-ch06-mcq-301', 'class9-ict-bn-guide', 'ict-lecture-satt', 'গ্রিডলাইন তুলে ফেলার জন্য কোনটিতে ক্লিক করতে হয়? (প্রয়োগ) করতে হবে? (প্রয়োগ)', 'mcq', '{"ক":"Show table","খ":"Style","গ":"Click ঘ","ঘ":"None"}'::jsonb, 'গ', null, 1, null, 'mcq_bank', null, 6, false),
