  ('ict-lec-mt-ch1-mcq-model-q-mcq-097', 'class9-ict-bn-guide', 'ict-lecture-satt', 'অ্যাডার মৃত্যুর কত বছর পর', 'mcq', '{"ক":"10","খ":"25","গ":"মাকর্ জুকারবাগর্ ক রেমন্ড স্যামুয়েল","ঘ":"আরপানেট ক যুক্তরাজ্যে ক যুক্তরাষ্ট্রে †cÖvMÖvwgs"}'::jsonb, 'ঘ', null, 1, 'ch1-mcq-model-q', 'model-mcq', null, 1, false),
  ('ict-lec-mt-ch1-model-saq-011', 'class9-ict-bn-guide', 'ict-lecture-satt', 'সনাতন পদ্ধতিতে পাঠদান এবং ই-', 'short', null, null, 'কুড়িগ্রামের রৌমারি উপজেলার যাদুর চর গ্রামের মিলন এখন নিজ গ্রামেই বসে উচ্চশিক্ষা গ্রহণ করতে পারবে, যা সম্ভব হবে ই-লানির্ং পদ্ধতির মাধ্যমে। ই-লানির্ং হলো ইলেকট্রনিক লানির্ং এর সংক্ষিপ্ত রূপ, যা ডিজিটাল প্রযুক্তির সাহায্যে শিক্ষালাভের একটি আধুনিক পদ্ধতি। বতর্মানে বিভিন্ন বিশ্ববিদ্যালয় ও শিক্ষাপ্রতিষ্ঠান তাদের কোসর্ অনলাইনে উন্মুক্ত করে দিয়েছে, ফলে শিক্ষাথীর্রা যে কোনো স্থান থেকে এই কোসর্ করতে পারে। মিলনও চাইলে এসব কোসের্ ভতির্ হয়ে ভিডিও লেকচার দেখতে, লাইভ ক্লাসে অংশ নিতে, হোমওয়াকর্ জমা দিতে এবং অনলাইন পরীক্ষায় অংশগ্রহণ করে ক্রেডিট অজর্ন করতে পারবে। তবে ই-লানির্ং ব্যবহারের জন্য মিলনের কাছে কম্পিউটার, উচ্চগতির ইন্টারনেট সংযোগ, আইএসপি ও প্রয়োজনীয় সফটওয়্যার থাকতে হবে। এই প্রযুক্তি ব্যবহার করে মিলন ঘরে বসেই উচ্চশিক্ষা চালিয়ে যেতে পারবে এবং নিজের স্বপ্ন পূরণের পথে এগিয়ে যেতে সক্ষম হবে। তথ্যপ্রযুক্তির উন্নতির ফলে গ্রামাঞ্চলেও উচ্চশিক্ষা এখন সহজলভ্য হয়ে উঠেছে।', null, null, 'short', null, 1, false),
